{"summary":"Added normalise.py with function normalise_temperature that normalises temperature values from Celsius or Fahrenheit to Celsius, raising ValueError for other units. Added tests/test_normalise.py with unittest testing the required cases.","files":[{"path":"normalise.py","content":"def normalise_temperature(value, unit):
    """Convert a temperature to Celsius.

    Args:
        value (float): Temperature value.
        unit (str): Unit of the temperature ('C' or 'F').

    Returns:
        float: Temperature in Celsius.

    Raises:
        ValueError: If unit is not 'C' or 'F'.
    """
    if unit == 'C':
        return value
    elif unit == 'F':
        return (value - 32) * 5 / 9
    else:
        raise ValueError(f"Unsupported unit: {unit}")
"},{"path":"tests/test_normalise.py","content":"import unittest
from normalise import normalise_temperature

class TestNormaliseTemperature(unittest.TestCase):
    def test_celsius_unchanged(self):
        self.assertEqual(normalise_temperature(32, 'C'), 32)

    def test_fahrenheit_to_celsius(self):
        self.assertAlmostEqual(normalise_temperature(32, 'F'), 0)
        self.assertAlmostEqual(normalise_temperature(212, 'F'), 100)

    def test_invalid_unit_raises(self):
        with self.assertRaises(ValueError):
            normalise_temperature(50, 'X')

if __name__ == '__main__':
